package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.*;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.*;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import static org.assertj.core.api.Assertions.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Reads persisted historical accounting snapshots via the real accounting authorization/DB API, not current-balance mocks. */
class FinanceInsightTrendIntegrationTest {
 static EmbeddedPostgres pg;static JdbcTemplate jdbc;static TransactionTemplate tx;static FinanceInsightService insights;
 static final UUID T=UUID.fromString("10000000-0000-0000-0000-000000000001");UUID hotel,company,book,actor;
 @BeforeAll static void start()throws Exception{pg=EmbeddedPostgres.builder().start();var ds=pg.getPostgresDatabase();jdbc=new JdbcTemplate(ds);jdbc.execute("create role hotel_ai_os_app nologin nosuperuser nobypassrls");Flyway.configure().dataSource(ds).locations("classpath:db/migration").target("93").load().migrate();var named=new NamedParameterJdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);tx=new TransactionTemplate(manager);var db=new TenantDatabaseContext(jdbc,true);var access=new AccessPolicy();var audit=new AuditWriter(named,e->{});var accounting=new FinanceAccountingService(named,db,access,audit,JSON);insights=new FinanceInsightService(named,db,access,audit,accounting,new FinanceAnalysisGateway("","","",false),manager);}
 @AfterAll static void stop()throws Exception{if(pg!=null)pg.close();}
 @AfterEach void clear(){TenantContext.clear();}
 @BeforeEach void seed(){hotel=UUID.randomUUID();company=UUID.randomUUID();book=UUID.randomUUID();actor=UUID.randomUUID();jdbc.update("insert into user_account(id,tenant_id,login_name,display_name) values(?,?,?,'同源趋势验收')",actor,T,actor.toString());jdbc.update("insert into org_unit(id,tenant_id,code,name,unit_type) values(?,?,?,'同源趋势门店','HOTEL')",hotel,T,hotel.toString());jdbc.update("insert into finance_company(id,tenant_id,name,tax_number) values(?,?,'同源趋势法人',?)",company,T,company.toString().replace("-",""));jdbc.update("insert into fa_book(id,tenant_id,hotel_id,company_id,name,start_month) values(?,?,?,?,'已冻结历史报表验收','2025-10-01')",book,T,hotel,company);TenantContext.set(new TenantPrincipal(T,actor,"TEST",Set.of("TEST"),Set.of("*"),Set.of(hotel),Set.of(),false,UUID.randomUUID()));statement("2026-10","100.00","60.00","40.00","20.00","FINAL","CURRENT");statement("2026-09","10.00","30.00","-20.00","10.00","FINAL","MOM");statement("2025-10","50.00","20.00","30.00","0.00","FINAL","YOY");}
 @Test void costsProfitAndCashTrendsReferenceBothExactHistoricalVersionsAndExportTheSameThreeStatements()throws Exception{var data=call(()->insights.dashboard("2026-10",hotel));assertThat(amount(fact(data,"expense:MOM").get("value"))).isEqualByComparingTo("100.000000");assertThat(amount(fact(data,"netProfit:MOM").get("value"))).isEqualByComparingTo("300.000000");assertThat(amount(fact(data,"CASH_NET_MOVEMENT:MOM").get("value"))).isEqualByComparingTo("100.000000");assertThat(fact(data,"expense:MOM")).containsEntry("sourceReportVersion",version("CURRENT")).containsEntry("comparisonSourceReportVersion",version("MOM")).containsEntry("comparisonMonth","2026-09");assertThat(fact(data,"OPERATING_PROFIT").get("value")).isNull();assertThat(fact(data,"WORK_HOURS").get("value")).isNull();var book=rows(data.get("books")).getFirst();assertThat(map(book.get("incomeStatement"))).containsEntry("expense","60.00");assertThat(map(book.get("cashFlowStatement"))).containsEntry("netMovement","20.00");var frozen=call(()->insights.freeze(new FinanceInsightModels.Generate(UUID.randomUUID(),"2026-10",hotel,data.get("reportVersion").toString())));var file=call(()->insights.export(null,null,id(frozen.get("snapshotId")),data.get("reportVersion").toString(),"xlsx"));try(var workbook=new org.apache.poi.xssf.usermodel.XSSFWorkbook(new java.io.ByteArrayInputStream(file.content()))){assertThat(workbook.getSheet("同源利润表汇总")).isNotNull();assertThat(workbook.getSheet("同源资产负债表汇总")).isNotNull();assertThat(workbook.getSheet("同源现金流量表汇总")).isNotNull();assertThat(workbook.getSheet("口径与冻结版本").getRow(0).getCell(1).getStringCellValue()).isEqualTo(data.get("reportVersion"));}}
 @Test void zeroHistoricalBaseAndIncompleteHistoryRemainNotComparableInsteadOfFictionalZeroOrGrowth(){var first=call(()->insights.dashboard("2026-10",hotel));assertThat(fact(first,"CASH_NET_MOVEMENT:YOY")).containsEntry("value",null).containsEntry("comparisonAmount","0.00").containsEntry("absoluteChange","20.00").containsEntry("complete",false);statement("2026-09","10.00","30.00","-20.00","10.00","INCOMPLETE","INCOMPLETE-MOM");var next=call(()->insights.dashboard("2026-10",hotel));assertThat(fact(next,"expense:MOM")).containsEntry("value",null).containsEntry("comparisonAmount",null).containsEntry("currentAmount",null).containsEntry("comparisonSourceState","INCOMPLETE").containsEntry("comparisonSourceReportVersion",version("INCOMPLETE-MOM"));assertThat(fact(next,"expense:MOM").get("explanation").toString()).contains("缺少完整");}
 @Test void anInsightSnapshotRetainsItsOwnPriorPeriodVersionsAfterControlledHistoryIsRevised(){var first=call(()->insights.dashboard("2026-10",hotel));var saved=call(()->insights.freeze(new FinanceInsightModels.Generate(UUID.randomUUID(),"2026-10",hotel,first.get("reportVersion").toString())));statement("2026-09","80.00","40.00","40.00","15.00","FINAL","MOM-REVISED");var latest=call(()->insights.dashboard("2026-10",hotel));assertThat(fact(latest,"expense:MOM")).containsEntry("comparisonSourceReportVersion",version("MOM-REVISED"));assertThat(amount(fact(latest,"expense:MOM").get("value"))).isEqualByComparingTo("50.000000");assertThat(latest.get("reportVersion")).isNotEqualTo(first.get("reportVersion"));var old=call(()->insights.snapshot(id(saved.get("snapshotId"))));assertThat(fact(old,"expense:MOM")).containsEntry("comparisonSourceReportVersion",version("MOM")).containsEntry("comparisonAmount","30.00");assertThat(amount(fact(old,"expense:MOM").get("value"))).isEqualByComparingTo("100.000000");}
 private void statement(String month,String revenue,String cost,String profit,String cash,String status,String revision){var snapshot=new LinkedHashMap<String,Object>();snapshot.put("book",Map.of("id",book,"hotelId",hotel,"companyId",company));snapshot.put("month",month);snapshot.put("status",status);snapshot.put("reportVersion",version(revision));snapshot.put("completeness",Map.of("complete",!status.equals("INCOMPLETE"),"checks",List.of()));snapshot.put("incomeStatement",Map.of("revenue",revenue,"expense",cost,"netProfit",profit,"lines",List.of()));snapshot.put("balanceSheet",Map.of("assets","200.00","liabilities","0.00","equity",new java.math.BigDecimal("200.00").subtract(amount(profit)).toPlainString(),"unclosedProfit",profit,"difference","0.00","lines",List.of()));snapshot.put("cashFlowStatement",Map.of("beginningCash","100.00","endingCash",amount(cash).add(new java.math.BigDecimal("100.00")).toPlainString(),"netMovement",cash,"difference","0.00","categories",Map.of("OPERATING",cash)));snapshot.put("detailLedger",List.of());snapshot.put("cashJournal",List.of());jdbc.update("insert into fa_period(tenant_id,book_id,month,status,close_snapshot,closed_by,closed_at) values(?, ?,?::date,'CLOSED',?::jsonb,?,now()) on conflict(tenant_id,book_id,month) do update set close_snapshot=excluded.close_snapshot",T,book,month+"-01",json(snapshot),actor);}
 private String version(String revision){return FinanceService.hash(book+":"+revision);}
 private Map<String,Object> fact(Map<String,Object> data,String suffix){return rows(data.get("facts")).stream().filter(row->row.get("id").equals(hotel+":"+suffix)).findFirst().orElseThrow();}
 private static <R> R call(Supplier<R> action){return tx.execute(s->{jdbc.execute("set local role hotel_ai_os_app");return action.get();});}
}
